    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 101 }],
  });
  assert.deepEqual(result, { ok: false, error: 'DISCOUNT_INVALID' });
});

test('createInvoice rejects negative discountPercent', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: -1 }],
  });
  assert.deepEqual(result, { ok: false, error: 'DISCOUNT_INVALID' });
});

test('createInvoice rejects non-numeric discountPercent', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: '10' }],
  });
  assert.deepEqual(result, { ok: false, error: 'DISCOUNT_INVALID' });
});

test('invoiceTotals includes discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 10 }],
  });
  const totals = invoiceTotals(result.value);
  // 100 * 9500 = 950000 (€9500.00)
  // 10% discount = 95000 (€950.00)
  // total = 855000 (€8550.00)
  assert.equal(totals.subtotal, 950000);
  assert.equal(totals.discount, 95000);
  assert.equal(totals.total, 855000);
});

test('invoiceTotals with multiple lines and different discounts', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'DES-HOUR', qty: 5, discountPercent: 20 },
    ],
  });
  const totals = invoiceTotals(result.value);
  // DEV: 10*9500=95000, discount 10%=9500
  // DES: 5*8500=42500, discount 20%=8500
  // subtotal: 95000+42500=137500
  // discount: 9500+8500=18000
  // total: 137500-18000=119500
  assert.equal(totals.subtotal, 137500);
  assert.equal(totals.discount, 18000);
  assert.equal(totals.total, 119500);
});

test('invoiceTotals clamps negative totals to 0', () => {
  const invoice = {
    customerId: 'C-001',
    customerName: 'Test',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 150 }],
  };
  const totals = invoiceTotals(invoice);
  // 10*1000=10000, discount 150%=15000
  // total would be -5000, clamped to 0
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 15000);
  assert.equal(totals.total, 0);
});

test('addLine accepts discountPercent', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const added = addLine(result.value, { sku: 'DES-HOUR', qty: 3, discountPercent: 15 });
  assert.equal(added.ok, true);
  assert.equal(added.value.lines[1].discountPercent, 15);
});

test('addLine rejects invalid discountPercent', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const added = addLine(result.value, { sku: 'DES-HOUR', qty: 3, discountPercent: 101 });
  assert.deepEqual(added, { ok: false, error: 'DISCOUNT_INVALID' });
});

test('addLine updates discount when updating existing line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 10 }],
  });
  const added = addLine(result.value, { sku: 'DEV-HOUR', qty: 5, discountPercent: 20 });
  assert.equal(added.ok, true);
  assert.equal(added.value.lines[0].qty, 10);
  assert.equal(added.value.lines[0].discountPercent, 20);
});

